    "summary": "Broker's outgoing timeout to shipping was reduced from 1000 ms to 4 ms, causing calls to shipping to time out."
  },
  "confidence": "high",
  "causal_chain": [
    {
      "claim": "At +47.379s ops recorded a config change that set broker timeout.shipping_ms to 4 ms (down from 1000 ms).",
      "status": "confirmed",
      "cites": ["ops-E0001"]
    },
    {
      "claim": "Starting at +47.478s the broker logged upstream timeout calls to shipping with timeout_ms=4.",
      "status": "confirmed",
      "cites": ["913f3b17"]
    },
    {
      "claim": "The broker’s timeout caused it to return 504 errors to ingest, which ingest logged as upstream_error 'dependency broker returned 504'.",
      "status": "confirmed",
      "cites": ["913f3b17"]
    },
    {
      "claim": "Ingest’s error propagated to the api, which logged upstream_error 'dependency ingest returned 504' and returned 504 to the user.",
      "status": "confirmed",
      "cites": ["913f3b17"]
    }
  ],
  "alternatives": [
    {
      "category": "dependency_slow",
      "service": "shipping",
      "why_less_likely": "Shipping metrics show normal request rates and latency throughout the window, with no spike in error rates or latency that would cause broker timeouts; the broker’s timeout value itself was changed to an unusually low 4 ms, pointing to a config issue rather than shipping slowness.",
